import "strconv"

func nextSmallestPalindrome(num int) int {
	// Check if all digits are '9'
	s := strconv.Itoa(num)
	all9 := true
	for _, ch := range s {
		if ch != '9' {
			all9 = false
			break
		}
	}
	if all9 {
		return num + 2
	}

	// Convert to digit slice
	digits := make([]int, len(s))
	for i, ch := range s {
		digits[i] = int(ch - '0')
	}

	n := len(digits)
	mid := n / 2
	leftSmaller := false

	// if n is odd, ignore the middle digit at first
	i := mid - 1
	j := mid
	if n%2 == 1 {
		j = mid + 1
	}

	for i >= 0 && digits[i] == digits[j] {
		i--
		j++
	}

	// stop if traverse end or difference found
	if i < 0 || digits[i] < digits[j] {
		leftSmaller = true
	}

	// copy left to right
	for i >= 0 {
		digits[j] = digits[i]
		j++
		i--
	}

	// the middle digit must be incremented
	if leftSmaller {
		carry := 1
		i = mid - 1
		if n%2 == 1 {
			digits[mid] += carry
			carry = digits[mid] / 10
			digits[mid] %= 10
			j = mid + 1
		} else {
			j = mid
		}
		for i >= 0 {
			digits[i] += carry
			carry = digits[i] / 10
			digits[i] %= 10
			digits[j] = digits[i]
			j++
			i--
		}
	}

	// Convert back to int
	res := 0
	for _, d := range digits {
		res = res*10 + d
	}
	return res
}

