package main

func isPalindrome(s string) bool {
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}

func makePalindrome(s string) string {
	if isPalindrome(s) {
		return s
	}
	for i := 0; i < len(s); i++ {
		if isPalindrome(s[i:]) {
			// append reverse of s[0:i]
			b := make([]byte, 0, len(s)+(i))
			b = append(b, s...)
			for k := i - 1; k >= 0; k-- {
				b = append(b, s[k])
			}
			return string(b)
		}
	}
	return s
}

